import React, { useState, useEffect, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios';
import Lottie from 'lottie-react';
import DOMPurify from 'dompurify';
import './Category.css';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';

/**
 * Category metadata configuration
 * Maps each category to its display properties, colors, icons,
 * video backgrounds, and Lottie animation sources.
 */
const categoryMeta = {
  dry: {
    title: 'Dry Items (Namkeen & Farsan)',
    icon: '🥨',
    desc: 'Crispy, crunchy savory snacks perfect for any time of the day. All our dry items are prepared fresh with traditional recipes.',
    color: '#D44444',
    gradient: 'from-red-600 to-red-800',
    bgLight: 'bg-orange-50',
    cardBg: 'from-orange-50 to-amber-50',
    videoPlaceholder: 'https://cdn.coverr.co/videos/coverr-cooking-snacks-in-kitchen-5690/1080p.mp4',
    // Lottie animation URL - free delivery animation from LottieFiles
    lottieUrl: 'https://assets10.lottiefiles.com/packages/lf20_w98qte06.json'
  },
  sweet: {
    title: 'Sweet Items (Longer Shelf Life)',
    icon: '🍬',
    desc: 'Traditional Maharashtrian sweets that stay fresh longer. Perfect for gifting, celebrations, and festive occasions.',
    color: '#FF6B35',
    gradient: 'from-orange-500 to-red-600',
    bgLight: 'bg-amber-50',
    cardBg: 'from-yellow-50 to-orange-50',
    videoPlaceholder: 'https://cdn.coverr.co/videos/coverr-pouring-honey-on-pancakes-2529/1080p.mp4',
    lottieUrl: 'https://assets2.lottiefiles.com/packages/lf20_ysas4vcp.json'
  },
  wet: {
    title: 'Wet/Fresh Sweets (Shorter Shelf Life)',
    icon: '🍮',
    desc: 'Freshly made premium sweets, best enjoyed within days. These require advance booking for guaranteed freshness.',
    color: '#8B4513',
    gradient: 'from-amber-700 to-brown-800',
    bgLight: 'bg-amber-50',
    cardBg: 'from-amber-50 to-yellow-50',
    videoPlaceholder: 'https://cdn.coverr.co/videos/coverr-making-dessert-in-kitchen-5668/1080p.mp4',
    lottieUrl: 'https://assets1.lottiefiles.com/packages/lf20_hl5imhpf.json'
  }
};

/**
 * ProductCard Component
 * Renders an individual product with hover animations, image placeholder,
 * price display, and add-to-cart functionality.
 * 
 * Security: All product descriptions are sanitized with DOMPurify before rendering.
 */
function ProductCard({ product, meta, onAddToCart }) {
  const [isHovered, setIsHovered] = useState(false);

  // Sanitize description to prevent XSS attacks
  const sanitizedDesc = DOMPurify.sanitize(product.description || '');

  return (
    <div
      className={`
        product-card group
        bg-white rounded-2xl overflow-hidden
        shadow-lg hover:shadow-2xl
        transform transition-all duration-500 ease-out
        ${isHovered ? 'scale-[1.03] -translate-y-2' : 'scale-100'}
      `}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Product Image Area with Gradient Overlay */}
      <div className="relative h-52 overflow-hidden">
        <div className={`w-full h-full bg-gradient-to-br ${meta.cardBg} flex items-center justify-center`}>
          <span className="text-7xl opacity-60 group-hover:scale-110 transition-transform duration-500">
            {meta.icon}
          </span>
        </div>
        
        {/* Price Badge */}
        <div className={`absolute top-3 right-3 bg-gradient-to-r ${meta.gradient} text-white px-4 py-1.5 rounded-full text-sm font-bold shadow-lg transform transition-all duration-300 ${isHovered ? 'scale-110' : ''}`}>
          ₹{product.price}/{product.unit}
        </div>

        {/* Availability Badge */}
        {product.is_regular ? (
          <div className="absolute top-3 left-3 bg-green-500 text-white px-3 py-1 rounded-full text-xs font-semibold shadow-md">
            ✅ In Stock
          </div>
        ) : (
          <div className="absolute top-3 left-3 bg-yellow-500 text-white px-3 py-1 rounded-full text-xs font-semibold shadow-md animate-pulse">
            ⏰ Advance Booking
          </div>
        )}

        {/* Overlay on hover */}
        <div className={`absolute inset-0 bg-black/10 transition-opacity duration-300 ${isHovered ? 'opacity-100' : 'opacity-0'}`}></div>
      </div>

      {/* Product Details */}
      <div className="p-5">
        <h3 className="text-lg font-bold text-gray-800 mb-1.5 group-hover:text-red-700 transition-colors duration-300">
          {product.name}
        </h3>
        {products.length === 0 ? (
          <div className="no-products">
            <span className="no-products-icon">📭</span>
            <h3>No products found in this category</h3>
            <p>Please check back later or explore other categories</p>
            <Link to="/" className="btn btn-primary">Back to Home</Link>
          </div>
        ) : (
          <div className="category-grid">
            {products.map(product => (
              <div key={product._id} className="product-card card">
                <div className="product-image">
                  <div className="product-image-placeholder" style={{ background: meta.bgGradient }}>
                    <span className="product-emoji">{meta.icon}</span>
                  </div>
                  {!product.is_regular && (
                    <span className="product-badge">Advance Booking</span>
                  )}
                </div>
                <div className="product-details">
                  <h3 className="product-name">{product.name}</h3>
                  <p className="product-desc">{product.description}</p>
                  <div className="product-meta">
                    <span className="product-price">₹{product.price}/{product.unit}</span>
                    {product.is_regular ? (
                      <span className="badge badge-primary">In Stock</span>
                    ) : (
                      <span className="badge badge-warning">On Order</span>
                    )}
                  </div>
                  <button
                    className="btn btn-primary add-to-cart-btn"
                    onClick={() => handleAddToCart(product)}
                  >
                    🛒 Add to Cart
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Delivery Info Bar */}
      <div className="delivery-info-bar">
        <div className="container delivery-info-content">
          <div className="delivery-info-item">
            <span>🚚</span>
            <span>Free delivery above ₹300</span>
          </div>
          <div className="delivery-info-item">
            <span>📅</span>
            <span>Next-day delivery for regular items</span>
          </div>
          <div className="delivery-info-item">
            <span>💳</span>
            <span>COD & UPI payments accepted</span>
          </div>
        </div>
      </div>

      {/* Toast */}
      {addedMsg && (
        <div className="toast-notification">
          <span>✅</span> {addedMsg} added to cart!
        </div>
      )}
    </div>
  );
}

export default Category;
